import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.hivrTVi-.js";const m=JSON.parse('{"title":"Inheritance Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/inheritance.md","filePath":"reference/inheritance.md"}'),n={name:"reference/inheritance.md"};function r(o,e,h,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="inheritance-reference" tabindex="-1">Inheritance Reference <a class="header-anchor" href="#inheritance-reference" aria-label="Permalink to &quot;Inheritance Reference&quot;">​</a></h1><p>This page documents the decision rules and mechanics of how PHP class hierarchy maps to OpenAPI composition in the spec pipeline. For usage examples see <a href="./../guide/spec-attributes.html#inheritance">Using Spec Attributes</a>.</p><p>Two augmenters handle inheritance: <a href="#schema-inheritance"><code>Inheritance</code></a> (schema composition via <code>allOf</code>) and <a href="#pathitem-inheritance"><code>PathItems</code></a> (prefix composition and metadata cloning).</p><h2 id="schema-inheritance" tabindex="-1">Schema Inheritance <a class="header-anchor" href="#schema-inheritance" aria-label="Permalink to &quot;Schema Inheritance&quot;">​</a></h2><p><strong>Augmenter:</strong> <code>OpenApi\\Augmenter\\Inheritance</code> · <strong>Phase:</strong> Resolve</p><p>The <code>Inheritance</code> augmenter walks the PHP class hierarchy for every schema that has a class reflector and expands it into OpenAPI <code>allOf</code> composition or inline property merging.</p><h3 id="decision-rules" tabindex="-1">Decision rules <a class="header-anchor" href="#decision-rules" aria-label="Permalink to &quot;Decision rules&quot;">​</a></h3><p>For each schema, the augmenter processes three relationship types in order:</p><ol><li><strong>Parents</strong> — walks up <code>getParentClass()</code> chain</li><li><strong>Traits</strong> — direct traits of the class, then traits of non-schema ancestors</li><li><strong>Interfaces</strong> — direct interfaces of the class</li></ol><p>For each ancestor encountered:</p><table tabindex="0"><thead><tr><th>Ancestor has <code>#[Schema]</code>?</th><th>Action</th><th>Continue walking?</th></tr></thead><tbody><tr><td>Yes</td><td>Add <code>$ref</code> to the schema&#39;s <code>allOf</code></td><td><strong>Stop</strong> (parents only)</td></tr><tr><td>No</td><td>Merge ancestor&#39;s <code>#[OA\\Property]</code> members inline</td><td>Continue</td></tr></tbody></table><h3 id="parent-chain-walk" tabindex="-1">Parent chain walk <a class="header-anchor" href="#parent-chain-walk" aria-label="Permalink to &quot;Parent chain walk&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class C extends B extends A</span></span></code></pre></div><ul><li>If <strong>B</strong> has a schema → <code>C.allOf</code> gets <code>$ref: B</code>, walk stops</li><li>If <strong>B</strong> has no schema but <strong>A</strong> does → B&#39;s properties merge into C, <code>C.allOf</code> gets <code>$ref: A</code></li><li>If neither has a schema → both B&#39;s and A&#39;s properties merge into C</li></ul><p>The &quot;stop at first schema ancestor&quot; rule prevents redundant references — B&#39;s schema already composes A if needed.</p><h3 id="trait-handling" tabindex="-1">Trait handling <a class="header-anchor" href="#trait-handling" aria-label="Permalink to &quot;Trait handling&quot;">​</a></h3><p>Traits are collected from two sources:</p><ol><li><strong>Direct traits</strong> of the schema&#39;s class</li><li><strong>Traits of non-schema ancestors</strong> — the augmenter walks up the parent chain until it hits an ancestor with a schema and collects traits from each non-schema ancestor along the way</li></ol><p>This ensures that when a non-schema parent uses a trait with <code>#[Schema]</code>, the composition is still captured.</p><h3 id="interface-handling" tabindex="-1">Interface handling <a class="header-anchor" href="#interface-handling" aria-label="Permalink to &quot;Interface handling&quot;">​</a></h3><p>Only <strong>direct</strong> interfaces of the schema&#39;s class are processed. Unlike parents, there is no stop-on-first-schema rule — all direct interfaces with schemas contribute a <code>$ref</code>.</p><h3 id="property-merging" tabindex="-1">Property merging <a class="header-anchor" href="#property-merging" aria-label="Permalink to &quot;Property merging&quot;">​</a></h3><p>When an ancestor has no schema, its <code>#[OA\\Property]</code> members are merged into the current schema. Deduplication is by property name — if the schema already declares a property with the same name, the ancestor&#39;s version is skipped. Merged properties are prepended to the schema&#39;s property list.</p><h3 id="allof-restructuring" tabindex="-1">allOf restructuring <a class="header-anchor" href="#allof-restructuring" aria-label="Permalink to &quot;allOf restructuring&quot;">​</a></h3><p>After expansion, if a schema has both <code>allOf</code> entries and its own properties, the compiler moves the properties into a dedicated <code>allOf</code> entry (an anonymous schema with <code>type: object</code>). This keeps the output clean:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">$ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;#/components/schemas/BaseModel&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">object</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      properties</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">string</span></span></code></pre></div><h3 id="duplicate-ref-deduplication" tabindex="-1">Duplicate $ref deduplication <a class="header-anchor" href="#duplicate-ref-deduplication" aria-label="Permalink to &quot;Duplicate $ref deduplication&quot;">​</a></h3><p>If you explicitly declare an <code>allOf</code> entry that matches one the augmenter would add (e.g. you extend a class and also manually reference it), the compiler deduplicates — only one <code>$ref</code> survives.</p><h2 id="pathitem-inheritance" tabindex="-1">PathItem Inheritance <a class="header-anchor" href="#pathitem-inheritance" aria-label="Permalink to &quot;PathItem Inheritance&quot;">​</a></h2><p><strong>Augmenter:</strong> <code>OpenApi\\Augmenter\\PathItems</code> · <strong>Phase:</strong> Resolve</p><p>The <code>PathItems</code> augmenter resolves how <code>#[OA\\PathItem]</code> attributes on controller classes compose via PHP inheritance to build operation paths and share metadata.</p><h3 id="prefix-composition" tabindex="-1">Prefix composition <a class="header-anchor" href="#prefix-composition" aria-label="Permalink to &quot;Prefix composition&quot;">​</a></h3><p>Each <code>PathItem</code> may declare a <code>prefix</code>. The augmenter composes prefixes by walking up the class hierarchy:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OA\\PathItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/v1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaseController</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OA\\PathItem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/users&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> UserController</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaseController</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span></code></pre></div><p>Resolution walks from the class to root, collects prefixes in ancestor order (root first), and joins them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/v1 + /users → /api/v1/users</span></span></code></pre></div><p>The resolved prefix is prepended to each operation&#39;s <code>path</code>. An operation with <code>path: &#39;/{id}&#39;</code> in <code>UserController</code> becomes <code>/api/v1/users/{id}</code>.</p><h3 id="governing-pathitem" tabindex="-1">Governing PathItem <a class="header-anchor" href="#governing-pathitem" aria-label="Permalink to &quot;Governing PathItem&quot;">​</a></h3><p>An operation&#39;s &quot;governing&quot; PathItem is found by walking up from the operation&#39;s declaring class until a class with <code>#[PathItem]</code> is found. Operations in a class without <code>#[PathItem]</code> can still inherit from an ancestor&#39;s PathItem.</p><h3 id="metadata-cloning" tabindex="-1">Metadata cloning <a class="header-anchor" href="#metadata-cloning" aria-label="Permalink to &quot;Metadata cloning&quot;">​</a></h3><p>The augmenter clones metadata from PathItem (and its ancestors) to operations:</p><table tabindex="0"><thead><tr><th>Property</th><th>Merge behavior</th></tr></thead><tbody><tr><td><code>tags</code></td><td>Accumulated from all ancestors, deduplicated, appended to operation&#39;s existing tags</td></tr><tr><td><code>security</code></td><td>Accumulated from all ancestors, deduplicated by scheme name</td></tr><tr><td><code>responses</code></td><td>Accumulated from all ancestors, deduplicated by response code — operation&#39;s own responses take precedence</td></tr></tbody></table><p>All three accumulate additively up the hierarchy — every ancestor&#39;s PathItem contributes.</p><h3 id="path-level-parameters" tabindex="-1">Path-level parameters <a class="header-anchor" href="#path-level-parameters" aria-label="Permalink to &quot;Path-level parameters&quot;">​</a></h3><p>PathItem <code>parameters</code> are inherited from ancestor PathItems and are emitted at the path level in the OpenAPI output. Deduplication is by <code>name + in</code> combination. The child&#39;s parameters take precedence over ancestors.</p><h3 id="path-level-output" tabindex="-1">Path-level output <a class="header-anchor" href="#path-level-output" aria-label="Permalink to &quot;Path-level output&quot;">​</a></h3><p>A PathItem with <code>parameters</code>, <code>summary</code>, <code>description</code>, or <code>servers</code> produces path-level output in the OpenAPI document. The augmenter resolves which operation paths map to this PathItem and emits the path-level properties for each.</p>`,47)])])}const k=a(n,[["render",r]]);export{m as __pageData,k as default};
